.github/workflows/*                 none    # exercised only by CI on push; local gates cannot run it
scripts/docker_acceptance_gate.sh   none    # Docker gate, run by hand; not one of the 6 gates
scripts/install.sh                  none
website/*                           none
deploy/*                            none    # container/procd packaging; Docker gate covers it
.gitignore                          none
.dockerignore                       none
LICENSE                             none

